head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > keepDataDragSelection]<br/>dataDragSelect=true 일때 마우스 우클릭 시 선택된 영역을 유지할지 설정합니다.",
    "validation" : [
        "useShiftKey=true 이고, dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성이 모두 false 인 경우에 동작합니다.",
        "true 설정 시, 마우스 우클릭 시 기존에 선택된 영역을 유지시키고 포커스를 이동하지 않습니다.",
        "true 설정 시, 마우스 오른쪽 버튼으로 Drag 시 Cell 선택(직사각형) 기능이 활성화됩니다.",
        "false 설정 시, 마우스 우클릭 시 기존에 선택된 영역을 해제하고 우클릭한 Cell 이 선택됩니다.",
        "미설정 시, 마우스 우클릭 시 기존에 선택된 영역을 해제하고 우클릭한 Cell 이 선택됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof dlt_src !== 'undefined') { $p.data.remove("dlt_src"); }

    // 전제 고정 : dataDragSelect=true + useShiftKey=true (dataDragDrop/Self/Other/Cell 미부여 → 기본 false)
    //  - con 은 keepDataDragSelection(미설정/true/false) 1개만 변경
    let vKeep = con_keepDataDragSelection.getText();

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    let lblKeep = (vKeep === '') ? '미설정(기본 false)' : vKeep;
    $c.gcm.createLabel('label="전제 고정 : dataDragSelect=true + useShiftKey=true (dataDragDrop 계열 모두 false). con(keepDataDragSelection=' + lblKeep + ') 적용. ① 좌클릭 Drag 로 직사각형 다중 Cell 을 선택 → ② 다른 Cell 에서 우클릭 → [선택 Cell 확인]. keep=true 면 기존 선택 영역이 유지(포커스 이동 안 함)되고, keep=false/미설정 이면 기존 선택이 해제되고 우클릭한 Cell 이 선택됩니다."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === DataList(dlt_src) : 4 Column [text, text, text, text] ===
    let strSrc = '';
    strSrc += '<w2:dataList ' + strNameSpace + ' id="dlt_src" baseNode="list" repeatNode="map">';
    strSrc += '<w2:columnInfo>';
    strSrc += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strSrc += '</w2:columnInfo>';
    strSrc += '<w2:data use="true"></w2:data>';
    strSrc += '</w2:dataList>';
    $p.data.create(strSrc);

    // 데이터 5행 로드
    let srcData = [
        { "col1": "행1", "col2": "100", "col3": "Aa", "col4": "10" },
        { "col1": "행2", "col2": "200", "col3": "Bb", "col4": "20" },
        { "col1": "행3", "col2": "300", "col3": "Cc", "col4": "30" },
        { "col1": "행4", "col2": "400", "col3": "Dd", "col4": "40" },
        { "col1": "행5", "col2": "500", "col3": "Ee", "col4": "50" }
    ];
    dlt_src.setJSON(srcData, false);

    let grp_comp = $c.gcm.getTestGroup();

    // === target1 : dataDragSelect=true + useShiftKey=true 고정, keepDataDragSelection 만 con 값으로 적용 ('' 이면 속성 미부여) ===
    let props = { dataList: "data:dlt_src", dataDragSelect: true, useShiftKey: true };
    if (vKeep === 'true') { props.keepDataDragSelection = true; } else if (vKeep === 'false') { props.keepDataDragSelection = false; }
    let srcCList = $c.gcm.createCList(props);

    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' ' + srcCList + ' id="" style="width:440px;height:300px;">';
    strTarget1 += '<w2:caption style="" id="caption1" value="target1 (keepDataDragSelection 테스트)"></w2:caption>';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget1, grp_comp);
};



// 선택 Cell 확인 : '시각적으로 선택(하이라이트)된' Cell 만 출력
//  - keepDataDragSelection 의 우클릭 동작은 화면 하이라이트(focusedTd 클래스)로 나타나므로, 선택 상태는 DOM 의 focusedTd td 로 판단한다.
//  - getAllFocusedIndex() 는 내부 focus 상태를 반환하므로 사용하지 않고, 실제 시각 선택만 집계한다.
scwin.btn_checkSelected_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    let opt = target1.options;
    b.setReturnValue("적용 : keepDataDragSelection=" + opt.keepDataDragSelection + " / dataDragSelect=" + opt.dataDragSelect + " / useShiftKey=" + opt.useShiftKey);

    // 시각적으로 선택(하이라이트)된 Cell td 수집 (id: ..._cell_{row}_{col})
    let tds = document.querySelectorAll("td[id*='target1_cell_']");
    let selected = [];
    for (let i = 0; i < tds.length; i++) {
        if ((tds[i].className || "").indexOf("focusedTd") >= 0) {
            let m = tds[i].id.match(/cell_(\d+)_(\d+)/);
            if (m) { selected.push({ row: parseInt(m[1], 10), col: parseInt(m[2], 10) }); }
        }
    }

    if (selected.length > 0) {
        b.setReturnValue("선택된 Cell 수 : " + selected.length);
        for (let j = 0; j < selected.length; j++) {
            b.setReturnValue("  row=" + selected[j].row + ", col=" + selected[j].col);
        }
    } else {
        b.setReturnValue("선택된 Cell 없음 (시각적 선택 상태)");
    }
};
